import java.io.*;
import java.util.*;

class Solution {
    private static final long MOD = 1_000_000_007L;

    public int makeStringSorted(String s) {
        int n = s.length();

        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1L;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }

        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n; i >= 1; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        int[] freq = new int[26];
        for (int i = 0; i < n; i++) {
            freq[s.charAt(i) - 'a']++;
        }

        long answer = 0L;

        for (int i = 0; i < n; i++) {
            int remaining = n - i;
            long ways = fact[remaining];

            for (int f : freq) {
                ways = ways * invFact[f] % MOD;
            }

            int idx = s.charAt(i) - 'a';
            int smaller = 0;
            for (int c = 0; c < idx; c++) {
                smaller += freq[c];
            }

            long invRemaining = fact[remaining - 1] * invFact[remaining] % MOD;
            answer = (answer + ways * smaller % MOD * invRemaining) % MOD;

            freq[idx]--;
        }

        return (int) answer;
    }

    private long modPow(long base, long exp) {
        long result = 1L;
        while (exp > 0) {
            if ((exp & 1L) != 0) result = result * base % MOD;
            base = base * base % MOD;
            exp >>= 1L;
        }
        return result;
    }
}

